#include "command.h"
uint8_t command_decode(const frame_t *f,command_t *out){command_t c={0};unsigned i,offset=0;uint8_t len=0;if(!f||!out)return NACK_PARAMETER;c.id=f->id;c.seq=f->seq;switch(f->id){case COMM_CMD_PING:case COMM_CMD_GET_INFO:case COMM_CMD_GET_STATE:case COMM_CMD_ENABLE:case COMM_CMD_DISABLE:case COMM_CMD_HOME:case COMM_CMD_TRAJECTORY_CLEAR:case COMM_CMD_STOP:case COMM_CMD_RESET_FAULT:case COMM_CMD_HEARTBEAT:break;case COMM_CMD_SET_JOINT:len=12;break;case COMM_CMD_TRAJECTORY_BEGIN:len=4;break;case COMM_CMD_TRAJECTORY_POINT:len=20;offset=8;break;case COMM_CMD_TRAJECTORY_START:len=2;break;case COMM_CMD_GRIPPER:len=1;break;default:return NACK_UNSUPPORTED;}if(f->length!=len)return NACK_LENGTH;if(f->id==COMM_CMD_GRIPPER){if(f->payload[0]>1)return NACK_PARAMETER;c.gripper=f->payload[0];}if(f->id==COMM_CMD_SET_JOINT||f->id==COMM_CMD_TRAJECTORY_POINT)for(i=0;i<3;i++)if(!protocol_float(f->payload+offset+4*i,&c.q[i]))return NACK_PARAMETER;if(f->id==COMM_CMD_TRAJECTORY_BEGIN||f->id==COMM_CMD_TRAJECTORY_POINT||f->id==COMM_CMD_TRAJECTORY_START)c.trajectory_id=protocol_u16(f->payload);if(f->id==COMM_CMD_TRAJECTORY_BEGIN){c.point_count=protocol_u16(f->payload+2);if(!c.point_count||c.point_count>COMM_TRAJECTORY_CAPACITY_POINTS)return NACK_PARAMETER;}if(f->id==COMM_CMD_TRAJECTORY_POINT){c.index=protocol_u16(f->payload+2);c.time_ms=protocol_u32(f->payload+4);if(c.index>=COMM_TRAJECTORY_CAPACITY_POINTS||(c.index==0&&c.time_ms!=0))return NACK_PARAMETER;}*out=c;return 0;}
